78	/**
79	 * Signs the user into OldDot when session and credentials are available,
80	 * then decides whether to stay in NewDot or switch to OldDot based on `nvp_tryNewDot`.
81	 */
82	function signInToOldDotAndChooseExperience(
83	    hybridApp: OnyxEntry<HybridApp>,
84	    tryNewDot: OnyxEntry<TryNewDot>,
85	    credentials: OnyxEntry<Credentials>,
86	    session: OnyxEntry<Session>,
87	    account: OnyxEntry<Account>,
88	) {
89	    if (!CONFIG.IS_HYBRID_APP) {
90	        return;
91	    }
92	
93	    if (!session?.authToken || !hybridApp?.useNewDotSignInPage) {
94	        return;
95	    }
96	
97	    if (isAnonymousUser(session)) {
98	        setReadyToShowAuthScreens(true);
99	        return;
100	    }
101	
102	    if (!credentials?.autoGeneratedLogin || !credentials?.autoGeneratedPassword || account?.requiresTwoFactorAuth === undefined || account?.needsTwoFactorAuthSetup === undefined) {
103	        return;
104	    }
105	
106	    // Skip if we're already in the signing in flow, preventing multiple calls to signInToOldDot
107	    if (session?.autoAuthState === CONST.AUTO_AUTH_STATE.SIGNING_IN) {
108	        return;
109	    }
110	
111	    Log.info(`[HybridApp] Performing sign-in on OldDot side`);
112	    HybridAppModule.signInToOldDot({
113	        autoGeneratedLogin: credentials.autoGeneratedLogin,
