[metadata] {"type": "create", "filePath": "/workspace/repo/src/libs/TryNewDotUtils.ts", "content": "import type {OnyxEntry} from 'react-native-onyx';
import type {TryNewDot} from '@src/types/onyx';
import {isEmptyObject} from '@src/types/utils/EmptyObject';

/**
 * Determines whether the user should be sent to the old app (Expensify Classic).
 *
 * Mobile-locked users (`isLockedToNewApp === true`) must always stay in NewApp, regardless of the
 * `classicRedirect.dismissed` value. For unlocked users, this follows the existing classic redirect logic.
 */
function shouldUseOldApp(tryNewDot: TryNewDot): boolean | undefined {
    if (tryNewDot?.isLockedToNewApp) {
        return false;
    }
    if (isEmptyObject(tryNewDot) || isEmptyObject(tryNewDot.classicRedirect)) {
        return true;
    }
    return tryNewDot.classicRedirect.dismissed;
}

/**
 * Determines whether redirecting back to the old app should be blocked because the user is mobile-locked.
 *
 * The mobile lock only applies when `shouldRespectMobileLock` is true (e.g. on mobile). On web the lock
 * does not apply, so this returns false even when `isLockedToNewApp` is true.
 */
function isOldAppRedirectBlocked(tryNewDot: OnyxEntry<TryNewDot>, shouldRespectMobileLock: boolean): boolean {
    return shouldRespectMobileLock && !!tryNewDot?.isLockedToNewApp;
}

/**
 * Determines whether the old app redirect affordance should be hidden.
 *
 * It is hidden while the lock state is still loading in a mobile-respecting context, or whenever the redirect
 * is blocked by the mobile lock. When `shouldRespectMobileLock` is false the redirect is never hidden, even
 * while the lock state is still loading.
 */
function shouldHideOldAppRedirect(tryNewDot: OnyxEntry<TryNewDot>, isLoadingTryNewDot: boolean, shouldRespectMobileLock: boolean): boolean {
    if (shouldRespectMobileLock && isLoadingTryNewDot) {
        return true;
    }
    return isOldAppRedirectBlocked(tryNewDot, shouldRespectMobileLock);
}

/**
 * Determines whether an old-app exit action should be blocked.
 *
 * The exit is blocked when the user is locked to the new app, or when the lock state is still resolving
 * (`isLoadingTryNewDot`) for an exit that would set the NVP (`shouldSetNVP`). Non-NVP-setting exits are never
 * blocked purely because of loading.
 */
function shouldBlockOldAppExit(tryNewDot: OnyxEntry<TryNewDot>, isLoadingTryNewDot: boolean, shouldSetNVP: boolean): boolean {
    if (tryNewDot?.isLockedToNewApp) {
        return true;
    }
    return isLoadingTryNewDot && shouldSetNVP;
}

export {shouldUseOldApp, isOldAppRedirectBlocked, shouldHideOldAppRedirect, shouldBlockOldAppExit};
