30	function useRedirectToExpensifyClassic() {
31	    const {translate} = useLocalize();
32	    const {showConfirmModal} = useConfirmModal();
33	    const [isTrackingGPS = false] = useOnyx(ONYXKEYS.GPS_DRAFT_DETAILS, {selector: isTrackingSelector});
34	    /**
35	     * There are scenarios where users who have not yet had their group workspace-chats in NewDot (isPolicyExpenseChatEnabled). In those scenarios, things can get confusing if they try to submit/track expenses. To address this, we block them from Creating, Tracking, Submitting expenses from NewDot if they are:
36	     * 1. on at least one group policy
37	     * 2. none of the group policies they are a member of have isPolicyExpenseChatEnabled=true
38	     */
39	    const [shouldRedirectToExpensifyClassic = false] = useOnyx(ONYXKEYS.COLLECTION.POLICY, {selector: shouldRedirectToExpensifyClassicSelector});
40	    const [tryNewDot] = useOnyx(ONYXKEYS.NVP_TRY_NEW_DOT);
41	    const [isLoadingTryNewDot = false] = useOnyx(ONYXKEYS.IS_LOADING_APP);
42	
43	    const canRedirectToExpensifyClassic = shouldRedirectToExpensifyClassic && !shouldHideOldAppRedirect(tryNewDot, isLoadingTryNewDot, CONFIG.IS_HYBRID_APP);
44	    const canUseAction = !shouldRedirectToExpensifyClassic || canRedirectToExpensifyClassic;
45	
46	    const showRedirectToExpensifyClassicModal = async () => {
47	        if (!canRedirectToExpensifyClassic) {
48	            return;
49	        }
50	        const {action} = await showConfirmModal({
51	            title: translate('sidebarScreen.redirectToExpensifyClassicModal.title'),
52	            prompt: translate('sidebarScreen.redirectToExpensifyClassicModal.description'),
53	            confirmText: translate('exitSurvey.goToExpensifyClassic'),
54	            cancelText: translate('common.cancel'),
55	        });
56	        if (action !== ModalActions.CONFIRM) {
57	            return;
58	        }
59	        if (CONFIG.IS_HYBRID_APP) {
60	            closeReactNativeApp({shouldSetNVP: true, isTrackingGPS});
61	            return;
62	        }
63	        openOldDotLink(CONST.OLDDOT_URLS.INBOX);
64	    };
65	
66	    return {shouldRedirectToExpensifyClassic, canRedirectToExpensifyClassic, canUseAction, showRedirectToExpensifyClassicModal};
67	}
